	["Adds a shield beside casts you cannot interrupt. Off keeps the usual cast bar."] = "A\195\177ade un escudo a los hechizos que no puedes interrumpir. Desactivado conserva la barra habitual.",
	["Adds a tick, triangle or square beside the threat border. Off keeps the border alone."] = "A\195\177ade una marca, tri\195\161ngulo o cuadrado junto al borde de amenaza. Desactivado muestra solo el borde.",
