	["Colours the fps and ms labels with the accent."] = "Colorea las etiquetas fps y ms con el acento.",
	["Colours the guild like the player's name. Off uses the guild colour."] = "Colorea la hermandad como el nombre del jugador. Desactivado usa el color de hermandad.",
	["Colours the highlight, the debuff borders and the type icon in the colours below."] = "Colorea el resaltado, los bordes de los perjuicios y el icono de tipo con los colores de abajo.",
	["Colours the mana in the mana colour or in one colour."] = "Colorea el man\195\161 con el color del man\195\161 o con un solo color.",
	["Colours the owner line like the pet's name. Off uses the owner colour."] = "Colorea la l\195\173nea del due\195\177o como el nombre de la mascota. Desactivado usa el color del due\195\177o.",
	["Colours the percentage by your threat. Off uses the frame's text colour."] = "Colorea el porcentaje seg\195\186n tu amenaza. Desactivado usa el color del texto del marco.",
	["Colours the plates of elites and bosses. Off, the gold diamond alone marks them."] = "Colorea las placas de \195\169lites y jefes. Desactivado, solo el rombo dorado los marca.",
	["Colours the plates of mobs one of your quests needs. Wins over the other types."] = "Colorea las placas de los enemigos que necesita una de tus misiones. Tiene prioridad sobre los dem\195\161s tipos.",
	["Colours the plates of mobs that have mana: the ones that cast and can be interrupted."] = "Colorea las placas de los enemigos con man\195\161: los que lanzan hechizos y se pueden interrumpir.",
	["Colours the plates of rare and rare elite mobs."] = "Colorea las placas de enemigos raros y \195\169lites raros.",
	["Colours the red ring of each debuff by its type, such as magic or poison."] = "Colorea el anillo rojo de cada perjuicio seg\195\186n su tipo, como magia o veneno.",
	["Colours the small mobs that come in swarms."] = "Colorea a los enemigos peque\195\177os que llegan en enjambres.",
	["Colours the threat percent with the threat colour. Off shows it in white."] = "Colorea el porcentaje de amenaza con su color. Desactivado, se muestra en blanco.",
	["Colours the unit's level from grey for trivial to red for far above you."] = "Colorea el nivel de la unidad, de gris si es trivial a rojo si te supera con creces.",
	["Colours the zone name plainly, by PvP status or with the accent."] = "Colorea el nombre de la zona sin m\195\161s, por estado JcJ o con el acento.",
	["Colours world bosses and skull-level mobs. Wins over rares and elites."] = "Colorea jefes del mundo y enemigos de nivel calavera. Prioridad sobre raros y \195\169lites.",
	["Colours your group's names inside say, yell, party, raid and instance messages."] = "Colorea los nombres de tu grupo en los mensajes de decir, gritar, grupo, banda e instancia.",
