	["Hides auras that never run out."] = "Oculta las auras que nunca expiran.",
	["Hides plates this far above or below you. 0 shows them at any height."] = "Oculta las placas a esta distancia por encima o por debajo de ti. 0 las muestra a cualquier altura.",
