	["Hides the meter while you play alone."] = "Oculta el medidor mientras juegas solo.",
	["Hides the size grip on docked chat windows, so the chat resizes only in Layout Mode."] = "Oculta el tirador de tama\195\177o de las ventanas acopladas; el chat solo cambia de tama\195\177o en el modo dise\195\177o.",
