	["Show yourself"] = "Mostrarte a ti",
	["Show zone level ranges on continent maps."] = "Muestra los niveles de las zonas en los mapas de continentes.",
	["Showing: %s"] = "Vista previa: %s",
	["Shown"] = "Visible",
