	["Shows 14:32 instead of 2:32 PM."] = "Muestra 14:32 en lugar de 2:32 p.m.",
	["Shows Bind keys buttons and a dash on unbound actions. Off keeps the usual binding display."] = "Muestra Asignar teclas y un guion en acciones sin tecla. Desactivado conserva la vista habitual.",
	["Shows Blizzard's art behind the Legacy pages instead of plain glass."] = "Muestra la ilustraci\195\179n de Blizzard tras las p\195\161ginas de Antiguo en lugar de cristal sin m\195\161s.",
	["Shows KstyleUI's bag bar in place of Blizzard's. Off, Blizzard's returns."] = "Muestra la barra de bolsas de KstyleUI en lugar de la de Blizzard. Desactivado, vuelve la de Blizzard.",
	["Shows KstyleUI's micro menu in place of Blizzard's. Off, Blizzard's returns."] = "Muestra el micromen\195\186 de KstyleUI en lugar del de Blizzard. Desactivado, vuelve el de Blizzard.",
	["Shows T, H or D in the role's colour instead of the role icon."] = "Muestra T, H o D en el color de la funci\195\179n en lugar del icono de funci\195\179n.",
	["Shows Zz while you rest in an inn or a city."] = "Muestra Zz mientras descansas en una posada o una ciudad.",
	["Shows a LibDataBroker plugin from another addon."] = "Muestra un complemento LibDataBroker de otro addon.",
	["Shows a bar for your main-hand swings."] = "Muestra una barra para tus golpes con la mano principal.",
	["Shows a bar for your off-hand swings."] = "Muestra una barra para tus golpes con la mano secundaria.",
	["Shows a bar for your ranged attacks."] = "Muestra una barra para tus ataques a distancia.",
	["Shows a buff you can cast on members who lack it, except while the game hides auras."] = "Muestra un beneficio que puedes lanzar en los miembros que no lo tienen, salvo mientras el juego oculta las auras.",
	["Shows a button on the damage meter's title that clears every fight, after combat."] = "Muestra en el t\195\173tulo del medidor un bot\195\179n que borra todos los combates, tras el combate.",
	["Shows a card of the spells you cast last, like the damage meter. Move it in Layout Mode."] = "Muestra una tarjeta de tus \195\186ltimos hechizos, como el medidor. Mu\195\169vela en el Modo dise\195\177o.",
	["Shows a crown when the unit leads the group."] = "Muestra una corona cuando la unidad lidera el grupo.",
	["Shows a debuff's tooltip when you point at its icon."] = "Muestra la descripci\195\179n de un perjuicio al se\195\177alar su icono.",
	["Shows a debuff's tooltip while you hover it. The plate behind the icon does not take the mouse."] = "Muestra la descripci\195\179n de un perjuicio al pasar el rat\195\179n. La placa tras el icono no recibe el rat\195\179n.",
	["Shows a faction badge after the names of units flagged for PvP."] = "Muestra una insignia de facci\195\179n tras el nombre de las unidades con JcJ activo.",
	["Shows a few debuffs on each frame."] = "Muestra algunos perjuicios en cada marco.",
	["Shows a friendly player's guild on a line under the name."] = "Muestra la hermandad de un jugador amistoso en una l\195\173nea bajo el nombre.",
	["Shows a heal's tooltip when you point at its icon."] = "Muestra la descripci\195\179n de una sanaci\195\179n al se\195\177alar su icono.",
