	["Shows a player's guild in angle brackets, green for your own guild."] = "Muestra la hermandad de un jugador entre comillas angulares, en verde para tu propia hermandad.",
	["Shows a portrait beside the bars."] = "Muestra un retrato junto a las barras.",
	["Shows a strip of the spells you cast last. Move it in Layout Mode."] = "Muestra una tira de tus \195\186ltimos hechizos. Mu\195\169vela en el Modo dise\195\177o.",
