	["Shows all your profiles, character and specialization choices, account preferences and profile hotkeys as one string to copy."] = "Muestra todos tus perfiles, elecciones de personaje y especializaci\195\179n, preferencias de cuenta y atajos de perfil como una cadena para copiar.",
	["Shows an envelope while you have unread mail."] = "Muestra un sobre mientras tienes correo sin leer.",
	["Shows an eye while you are queued, in place of Blizzard's queue eye."] = "Muestra un ojo mientras est\195\161s en cola, en lugar del ojo de cola de Blizzard.",
	["Shows an item, spell or quest tooltip while the pointer is over its link in chat."] = "Muestra la descripci\195\179n de un objeto, hechizo o misi\195\179n mientras el puntero est\195\161 sobre su enlace.",
	["Shows another damage meter with its own Show and Fight. Move it in Layout Mode."] = "Muestra otro medidor de da\195\177o con sus propios Mostrar y Combate. Mu\195\169velo en el Modo dise\195\177o.",
