	["Shows each debuff's type symbol, such as magic or poison, in a corner, on an edge or in the centre."] = "Muestra el s\195\173mbolo de tipo de cada perjuicio, como magia o veneno, en una esquina, en un borde o en el centro.",
	["Shows each member's answer during a ready check."] = "Muestra la respuesta de cada miembro durante una comprobaci\195\179n de listos.",
