	["Shows each share of the total, when the game lets addons read it."] = "Muestra la parte de cada uno sobre el total, cuando el juego permite a los addons leerla.",
	["Shows experience, or watched reputation at the level cap."] = "Muestra experiencia o la reputaci\195\179n seguida al nivel m\195\161ximo.",
