	["Shows how far your rested experience reaches past your current experience."] = "Muestra hasta d\195\179nde llega tu experiencia de descanso m\195\161s all\195\161 de tu experiencia actual.",
	["Shows how long KstyleUI takes each frame, refreshed while this page is open."] = "Muestra cu\195\161nto tarda KstyleUI en cada fotograma; se actualiza mientras esta p\195\161gina est\195\161 abierta.",
	["Shows how long the current or last fight lasted."] = "Muestra cu\195\161nto dura el combate actual o dur\195\179 el \195\186ltimo.",
	["Shows how long you have been in combat. Move it in Layout Mode."] = "Muestra cu\195\161nto tiempo llevas en combate. Mu\195\169velo en el Modo dise\195\177o.",
