	["Shows only auras you cast."] = "Muestra solo las auras que lanzas t\195\186.",
	["Shows only debuffs you can dispel; for buffs, only ones you can apply."] = "Solo perjuicios que puedes disipar; para beneficios, los que puedes aplicar.",
