	["Shows the mana, rage, energy and other power you gain, with a plus sign."] = "Muestra el man\195\161, la ira, la energ\195\173a y otros recursos que obtienes, con un signo m\195\161s.",
	["Shows the maximum stack line only while this key is held."] = "Muestra la l\195\173nea de pila m\195\161xima solo mientras mantienes esta tecla.",
	["Shows the meter's name and column heading above the rows."] = "Muestra el nombre del medidor y el encabezado de columna sobre las filas.",
	["Shows the money earned or spent this session in the gold tooltip."] = "Muestra en la descripci\195\179n del oro el dinero ganado o gastado en esta sesi\195\179n.",
	["Shows the name of each macro."] = "Muestra el nombre de cada macro.",
	["Shows the name of the spell being cast."] = "Muestra el nombre del hechizo que se est\195\161 lanzando.",
	["Shows the open page's sections; right-click a page to fold them. Off lists pages only."] = "Muestra las secciones de la p\195\161gina abierta; clic derecho en una p\195\161gina para plegarlas. Desactivado lista solo p\195\161ginas.",
	["Shows the pins addons such as guides park on the map's edge for places off the map."] = "Muestra los marcadores que addons como las gu\195\173as colocan en el borde del mapa para lugares fuera de \195\169l.",
	["Shows the power bar on damage dealers' frames; off gives their health bar the room."] = "Muestra la barra de poder en los marcos de da\195\177o; desactivado, la barra de salud ocupa el espacio.",
