	["Shows the raid marker, such as a skull, set on a member."] = "Muestra el marcador de banda, como una calavera, puesto en un miembro.",
	["Shows the reset button only while you point at the meter."] = "Muestra el bot\195\179n de reinicio solo mientras se\195\177alas el medidor.",
	["Shows the role icon on damage dealers."] = "Muestra el icono de funci\195\179n en los de da\195\177o.",
