	["Shows the seconds left on the cast bar."] = "Muestra los segundos restantes en la barra de lanzamiento.",
	["Shows the seconds left until the next swing."] = "Muestra los segundos que faltan para el pr\195\179ximo golpe.",
	["Shows the spell a unit is casting under its health bar."] = "Muestra bajo su barra de salud el hechizo que est\195\161 lanzando una unidad.",
