	["Shows the spell's name on the cast bar."] = "Muestra el nombre del hechizo en la barra de lanzamiento.",
	["Shows the text only while the pointer is over the bar."] = "Muestra el texto solo mientras el puntero est\195\161 sobre la barra.",
	["Shows the time left before your PvP flag drops, after the status icons."] = "Muestra tras los iconos de estado el tiempo que queda hasta que termine tu estado JcJ.",
