	["Shows the unit's buffs and debuffs beside the frame."] = "Muestra los beneficios y perjuicios de la unidad junto al marco.",
	["Shows the unit's casts and channels."] = "Muestra los lanzamientos y canalizaciones de la unidad.",
	["Shows the unit's group role."] = "Muestra la funci\195\179n de la unidad en el grupo.",
	["Shows the unit's health on a KstyleUI bar under the tooltip."] = "Muestra la salud de la unidad en una barra de KstyleUI bajo la descripci\195\179n.",
	["Shows the unit's level in a badge on the portrait, or after the name."] = "Muestra el nivel de la unidad en una insignia sobre el retrato, o tras el nombre.",
	["Shows the unit's mana, rage, energy or focus under its health."] = "Muestra el man\195\161, la ira, la energ\195\173a o el enfoque de la unidad bajo su salud.",
	["Shows the unit's name."] = "Muestra el nombre de la unidad.",
	["Shows the volume. Click: mute or unmute all sound."] = "Muestra el volumen. Clic: silenciar o reactivar todo el sonido.",
	["Shows the whole name, its first or last word, or the first words as initials."] = "Muestra el nombre completo, su primera o \195\186ltima palabra, o las primeras palabras como iniciales.",
	["Shows the zone name under the map's left edge."] = "Muestra el nombre de la zona bajo el borde izquierdo del mapa.",
	["Shows these states in the ready-check space. Off leaves only ready checks."] = "Muestra estos estados en el espacio de comprobaci\195\179n. Desactivado deja solo las comprobaciones.",
	["Shows this button among the chat buttons."] = "Muestra este bot\195\179n entre los botones del chat.",
	["Shows this indicator on party and raid frames, or on one kind only."] = "Muestra este indicador en los marcos de grupo y de banda, o solo en uno de ellos.",
	["Shows this profile as a string you can copy and share."] = "Muestra este perfil como un texto que puedes copiar y compartir.",
	["Shows this raid group's members. The groups shown close up, in order."] = "Muestra los miembros de este grupo de banda. Los grupos mostrados se juntan, en orden.",
