	["Shows your combo points on your target's plate, as the unit frames' pips."] = "Muestra tus puntos de combo en la placa de tu objetivo, como los puntos de los marcos de unidad.",
	["Shows your current zone."] = "Muestra tu zona actual.",
	["Shows your frame even when you are not in a group."] = "Muestra tu marco aunque no est\195\169s en grupo.",
	["Shows your group's threat on your target when role-based meters are off."] = "Muestra la amenaza del grupo sobre tu objetivo cuando el modo por rol est\195\161 desactivado.",
