	["Shows your lowest equipped durability."] = "Muestra la menor durabilidad de tu equipo.",
	["Shows your mana in bear and cat form."] = "Muestra tu man\195\161 en forma de oso y felina.",
	["Shows your map coordinates."] = "Muestra tus coordenadas en el mapa.",
