	["Welcome"] = "Bienvenida",
	["Welcome text, the French and German Options footer, the 1080p data bar and colour-vision health bars read right."] = "El texto de bienvenida, el pie de las opciones en franc\195\169s y alem\195\161n, la barra de datos a 1080p y las barras de salud para daltonismo se leen bien.",
	["Welcome to KstyleUI"] = "Te damos la bienvenida a KstyleUI",
	["What happens when you learn a higher rank of a spell on your bars."] = "Qu\195\169 pasa cuando aprendes un rango superior de un hechizo que tienes en tus barras.",
	["What happens when you learn an active spell that is not on your bars."] = "Qu\195\169 hacer al aprender un hechizo activo que no est\195\161 en tus barras.",
	["What the bag window shows each time it opens."] = "Lo que muestra la ventana de bolsas cada vez que se abre.",
	["What the health text shows."] = "Qu\195\169 muestra el texto de salud.",
	["What the readout adds for the middle click. Needs a middle click other than None."] = "Lo que el indicador a\195\177ade para el clic central. Requiere un clic central distinto de Ninguno.",
	["What the readout adds for the right click. Needs a right click other than None."] = "Lo que el indicador a\195\177ade para el clic derecho. Requiere un clic derecho distinto de Ninguno.",
	["What the readout shows for the left click: the destination, its cooldown or both."] = "Lo que el indicador muestra para el clic izquierdo: el destino, su tiempo de reutilizaci\195\179n o ambos.",
	["What the text on the bar says."] = "Qu\195\169 dice el texto de la barra.",
	["What the window measures. Click its title to switch between damage and healing in game."] = "Lo que mide la ventana. Haz clic en su t\195\173tulo en el juego para cambiar entre da\195\177o y sanaci\195\179n.",
	["What this indicator shows; slots sharing a place sit side by side."] = "Qu\195\169 muestra este indicador; los huecos que comparten lugar se colocan uno junto a otro.",
	["What this readout shows on one line. Data bar's choice follows Icons."] = "Lo que este indicador muestra en una l\195\173nea. Como la barra de datos sigue a Iconos.",
	["What your bags do when this window opens and closes. Closing only closes bags it opened."] = "Qu\195\169 hacen tus bolsas al abrirse y cerrarse esta ventana. Solo cierra las bolsas que abri\195\179.",
	["What's new"] = "Novedades",
	["Wheel between maps"] = "Cambiar de mapa con la rueda",
	["Wheel out past a map's edge to its parent, or in over a zone to open it."] = "Aleja al l\195\173mite para abrir el mapa superior, o acerca sobre una zona para abrirla.",
	["When a condition matches"] = "Al cumplirse una condici\195\179n",
	["When all layouts are full, choose one to replace. Off keeps the previous full-list message."] = "Si todos los dise\195\177os est\195\161n ocupados, elige uno para reemplazar. Desactivado conserva el aviso anterior.",
	["When hovering a button shows its tooltip."] = "Cu\195\161ndo muestra un bot\195\179n su descripci\195\179n al pasar el rat\195\179n.",
	["When hovering a unit frame shows the unit's tooltip."] = "Cu\195\161ndo pasar el rat\195\179n sobre un marco de unidad muestra la descripci\195\179n de la unidad.",
	["When hovering an icon shows its tooltip."] = "Cu\195\161ndo pasar el cursor sobre un icono muestra su descripci\195\179n.",
	["When solo only"] = "Solo sin grupo",
	["When the colours are close, draws power in steel with a thin line of its original colour."] = "Si los colores son similares, muestra el recurso en gris acero con una l\195\173nea fina de su color original.",
	["When the crosshair shows."] = "Cu\195\161ndo se muestra la mira.",
	["When the cursor ring shows."] = "Cu\195\161ndo se muestra el anillo del cursor.",
	["When the element shows."] = "Cu\195\161ndo se muestra el elemento.",
	["When the game auto loots, take every item the moment the window opens."] = "Cuando el juego despoja autom\195\161ticamente, lo toma todo al abrirse la ventana.",
	["When the member's tooltip shows as you point at a frame."] = "Cu\195\161ndo aparece la descripci\195\179n del miembro al se\195\177alar un marco.",
	["When these hide, the icons after them move up, even with Close gaps off."] = "Cuando estos se ocultan, los iconos siguientes avanzan, aunque Cerrar huecos est\195\169 desactivado.",
	["Where Dead, Ghost and Offline sit on the health bar."] = "D\195\179nde se colocan Muerto, Fantasma y Desconectado en la barra de salud.",
	["Where a short row starts."] = "D\195\179nde empieza una fila incompleta.",
