	["Where each debuff's stacks sit."] = "D\195\179nde se sit\195\186an las acumulaciones de cada perjuicio.",
	["Where each debuff's time left sits."] = "D\195\179nde se sit\195\186a el tiempo restante de cada perjuicio.",
	["Where each value sits in its cell. One line sizes each readout to its text."] = "D\195\179nde se sit\195\186a cada valor en su celda. En una l\195\173nea, cada indicador se ajusta a su texto.",
	["Where it sits inside the map's edge."] = "D\195\179nde se sit\195\186a dentro del borde del mapa.",
	["Where numbers show"] = "D\195\179nde se muestran los n\195\186meros",
	["Where on the frame the indicator sits."] = "D\195\179nde se coloca el indicador en el marco.",
