	["Where on the health bar the ready check, resurrection, summon and AFK icons sit."] = "D\195\179nde se colocan en la barra de salud los iconos de comprobaci\195\179n de listos, resurrecci\195\179n, invocaci\195\179n y ausente.",
	["Where on the icon the stack count sits: in a corner, on an edge or in the centre."] = "D\195\179nde va el n\195\186mero de acumulaciones en el icono: en una esquina, en un borde o en el centro.",
	["Where the bar's colour comes from."] = "De d\195\179nde viene el color de la barra.",
